#ifndef ONEWIRE_H
#define ONEWIRE_H

#include <stdbool.h>
#include <stdint.h>

/**
 * @brief Performs a 1-Wire bus reset and probes for connected slave devices.
 * 
 * This function handles the initial handshake phase of the 1-Wire protocol. It 
 * generates a master reset pulse to clear the bus and subsequently samples the line 
 * to detect the hardware presence pulse generated by any connected slave devices.
 * 
 * @return true if a slave device successfully asserted a presence pulse, false otherwise.
 */
bool oneWireReset(void);

/**
 * @brief Transmits a single raw bit of data over the 1-Wire bus.
 * 
 * Establishes a synchronized time slot to write a single logical state (0 or 1) 
 * to the bus. This operation executes deterministically to adhere to strict hardware 
 * bus line constraints.
 * 
 * @param bit The logical state to transmit (true for 1, false for 0).
 */
void oneWireWriteBit(bool bit);

/**
 * @brief Samples and reads a single raw bit of data from the 1-Wire bus.
 * 
 * Initiates a read time slot, releases ownership of the bus line immediately to allow 
 * the slave device to drive the state, and captures the logical signal voltage level 
 * at the precise protocol sampling window.
 * 
 * @return true if a logical 1 was sampled, false if a logical 0 was sampled.
 */
bool oneWireReadBit(void);

/**
 * @brief Transmits a full 8-bit data frame over the 1-Wire bus.
 * 
 * Serializes an entire data byte and streams it onto the bus bit-by-bit. 
 * In accordance with standard 1-Wire specifications, transmission is handled 
 * Least Significant Bit (LSB) first.
 * 
 * @param byte The 8-bit command, address, or configuration data to write.
 */
void oneWireWriteByte(uint8_t byte);

/**
 * @brief Reads and reconstructs a full 8-bit data frame from the 1-Wire bus.
 * 
 * Synchronously polls the bus line for 8 consecutive data slots, shifting and 
 * assembling the incoming stream into a complete byte. Data is captured and 
 * processed Least Significant Bit (LSB) first.
 * 
 * @return uint8_t The fully compiled 8-bit data block received from the bus.
 */
uint8_t oneWireReadByte(void);

#endif // ONEWIRE_H
